import heapq

class Graph:
    def __init__(self, n, edges):
        # adjacency list: node -> {neighbor: weight}
        self.graph = {i: {} for i in range(n)}
        for u, v, w in edges:
            self.graph[u][v] = w

    def addEdge(self, edge):
        # insert edge u -> v with weight w (keep the smaller weight if it somehow exists)
        u, v, w = edge
        if v in self.graph[u]:
            self.graph[u][v] = min(self.graph[u][v], w)
        else:
            self.graph[u][v] = w

    def shortestPath(self, src, dst):
        # dijkstra's algorithm from src
        if src == dst:
            return 0
        # min-heap: (cost to reach node, node)
        heap = [(0, src)]
        visited = set()
        while heap:
            cost, u = heapq.heappop(heap)
            if u == dst:
                return cost
            if u in visited:
                continue
            visited.add(u)
            for v, w in self.graph[u].items():
                if v not in visited:
                    heapq.heappush(heap, (cost + w, v))
        return -1
